/* HEXA BATTLEGROUNDS upgrade2 — PART 14 OF 25. For databases that already ran supabase/upgrade (match phases); Run in order. Safe to re-run. */ do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pic-0', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🪜 + 👨\n\n(10 letters · starts with S)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🧈 + 🪰\n\n(9 letters · starts with B)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🍯 + 🌙\n\n(9 letters · starts with H)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["STEPFATHER"]},{"label":"Picture 2 (Decoder)","accept":["BUTTERFLY"]},{"label":"Picture 3 (Intel)","accept":["HONEYMOON"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: ST…, BU…, HO…', 'STEPFATHER: step + father | BUTTERFLY: butter + fly | HONEYMOON: honey + moon', null, 25, 'published'), ('mission-pic-1', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"💡 + 🏠\n\n(10 letters · starts with L)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🔥 + 🧱\n\n(8 letters · starts with F)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"🔥 + 🦊\n\n(7 letters · starts with F)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["LIGHTHOUSE"]},{"label":"Picture 2 (Decoder)","accept":["FIREWALL"]},{"label":"Picture 3 (Intel)","accept":["FIREFOX"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: LI…, FI…, FI…', 'LIGHTHOUSE: light + house | FIREWALL: fire + wall | FIREFOX: fire + fox', null, 25, 'published'), ('mission-pic-2', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🌧️ + 🎀\n\n(7 letters · starts with R)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🦶 + ⚽\n\n(8 letters · starts with F)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"⭐ + 🐟\n\n(8 letters · starts with S)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["RAINBOW"]},{"label":"Picture 2 (Decoder)","accept":["FOOTBALL"]},{"label":"Picture 3 (Intel)","accept":["STARFISH"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: RA…, FO…, ST…', 'RAINBOW: rain + bow | FOOTBALL: foot + ball | STARFISH: star + fish', null, 25, 'published'), ('mission-pic-3', 'picture', 'mission', 'Picture Riddles', 'picture', 1, array['any','learning','social','office','coffee','public']::text[], 'Each teammate holds one picture riddle: two pictures make one word. Solve all three.', '{"scout":{"title":"Picture 1","body":"🥚 + 🍆\n\n(8 letters · starts with E)","mono":false,"big":true},"decoder":{"title":"Picture 2","body":"🐎 + 👞\n\n(9 letters · starts with H)","mono":false,"big":true},"intel":{"title":"Picture 3","body":"✋ + 👜\n\n(7 letters · starts with H)","mono":false,"big":true}}'::jsonb, '[{"label":"Picture 1 (Scout)","accept":["EGGPLANT"]},{"label":"Picture 2 (Decoder)","accept":["HORSESHOE"]},{"label":"Picture 3 (Intel)","accept":["HANDBAG"]}]'::jsonb, false, 3, 200, 'Say each emoji out loud and join the words: 🪜 + 👨 = STEP + FATHER. Answers start with: EG…, HO…, HA…', 'EGGPLANT: egg + plant | HORSESHOE: horse + shoe | HANDBAG: hand + bag', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
